//! Conversation layout, composer attachments, and browser speech.
//! The transcript and composer stay the shell's; this module only decides
//! layout class names, file limits, and the speech/upload helpers.

use std::cell::RefCell;
use std::rc::Rc;

use leptos::prelude::*;
use serde::Deserialize;
use wasm_bindgen::closure::Closure;
use wasm_bindgen::{JsCast, JsValue};

use crate::api;

pub const MAX_ATTACHMENT_BYTES: usize = 5 * 1024 * 1024;
pub const MAX_ATTACHMENTS: usize = 8;

/// Fixed prompts shown under a reply in conversation layout.
/// These are not generated by the model.
pub const FOLLOW_UPS: [&str; 3] = ["Go on", "Make that shorter", "What should I check next?"];

#[derive(Clone)]
pub struct PendingAttachment {
    pub id: u32,
    pub name: String,
    pub mime: String,
    pub bytes: u64,
    pub preview: String,
    pub data_b64: String,
    pub error: String,
    pub uploaded_ref: String,
    pub uploaded_kind: String,
    pub uploaded_sha: String,
}

impl Default for PendingAttachment {
    fn default() -> Self {
        Self {
            id: 0,
            name: String::new(),
            mime: String::new(),
            bytes: 0,
            preview: String::new(),
            data_b64: String::new(),
            error: String::new(),
            uploaded_ref: String::new(),
            uploaded_kind: String::new(),
            uploaded_sha: String::new(),
        }
    }
}

#[derive(Clone, Deserialize)]
pub struct Uploaded {
    #[serde(rename = "ref")]
    pub reference: String,
    #[serde(default)]
    pub sha256: String,
    #[serde(default)]
    pub bytes: i64,
    #[serde(default)]
    pub mime: String,
    #[serde(default)]
    pub kind: String,
    #[serde(default)]
    pub name: String,
}

pub fn normalize_layout(raw: &str) -> String {
    if raw == "conversation" {
        "conversation".into()
    } else {
        "cockpit".into()
    }
}

pub fn shell_class(focus: bool, layout: &str, sessions: bool, panel: bool) -> String {
    let conversation = layout == "conversation";
    let mut class = String::from("shell");
    if focus && !conversation {
        class.push_str(" focus");
    }
    if conversation {
        class.push_str(" layout-conversation");
        if sessions {
            class.push_str(" drawer-sessions");
        }
        if panel {
            class.push_str(" drawer-panel");
        }
    }
    class
}

pub fn reconnect_delay_ms(attempt: u32) -> i32 {
    1000 * (1 << attempt.min(3))
}

pub fn accept_local(already: usize, size: u64) -> Result<(), String> {
    if already >= MAX_ATTACHMENTS {
        return Err(format!("only {MAX_ATTACHMENTS} attachments per message"));
    }
    if size == 0 {
        return Err("file is empty".into());
    }
    if size > MAX_ATTACHMENT_BYTES as u64 {
        return Err(format!(
            "file exceeds {} MiB",
            MAX_ATTACHMENT_BYTES / (1024 * 1024)
        ));
    }
    Ok(())
}

/// Puts a failed send back without erasing text the user typed while it
/// was in flight. `current` is whatever is in the composer now.
pub fn merge_failed_send(current: &str, failed: &str) -> String {
    if current.is_empty() {
        return failed.to_string();
    }
    if failed.is_empty() || current == failed {
        return current.to_string();
    }
    let mut out = failed.to_string();
    if !out.ends_with(' ') && !out.ends_with('\n') {
        out.push(' ');
    }
    out.push_str(current);
    out
}

/// Keeps files added while a send was in flight, and puts the failed batch
/// back in front of them.
pub fn merge_failed_files(
    failed: Vec<PendingAttachment>,
    current: Vec<PendingAttachment>,
) -> Vec<PendingAttachment> {
    merge_failed_files_capped(failed, current).0
}

/// `merge_failed_files` with the per-message cap enforced (#1652): the
/// failed batch stays in front, current files follow, and the merged list
/// is truncated to `MAX_ATTACHMENTS`. Returns the merged rows plus how
/// many rows the cap dropped, so the caller can tell the user instead of
/// silently losing files (an over-cap restore used to resend >8 files,
/// get a daemon 400, and loop forever). Rows removed by the id dedupe
/// are not counted as dropped — they are the same file, not a lost one.
pub fn merge_failed_files_capped(
    failed: Vec<PendingAttachment>,
    current: Vec<PendingAttachment>,
) -> (Vec<PendingAttachment>, usize) {
    let mut merged = failed;
    for row in current {
        if !merged.iter().any(|f| f.id == row.id) {
            merged.push(row);
        }
    }
    let dropped = merged.len().saturating_sub(MAX_ATTACHMENTS);
    merged.truncate(MAX_ATTACHMENTS);
    (merged, dropped)
}

/// Status line for a failed-send restore that dropped rows at the cap.
/// Reuses the `accept_local` cap wording so the limit reads the same
/// everywhere it is enforced.
pub fn restore_drop_notice(dropped: usize) -> String {
    let noun = if dropped == 1 {
        "attachment was"
    } else {
        "attachments were"
    };
    format!("{dropped} {noun} not restored: only {MAX_ATTACHMENTS} attachments per message")
}

/// Mints attachment row ids (#1658). The old mint derived the id from the
/// wall clock alone — `(Date::now() as u64) * 16 + index-in-batch` as
/// `u32` — so two batches landing in the same millisecond minted identical
/// ids for distinct files, and every consumer (FileReader completion,
/// `mark_error`, Remove, restore dedupe) keys on the id alone, first match
/// wins. This mint is seeded from the clock once and then simply counts
/// up: ids are unique by construction for the life of the page, no matter
/// how batches interleave, and stay roughly time-ordered (the seed) for
/// debugging. The id space repeats only after 2^32 mints in one page
/// session — the old truncation repeated every 2^28 ms (≈3.1 days) even
/// with no collision in a single batch.
#[derive(Debug, Clone)]
pub struct AttachmentIdMint {
    next: u32,
}

impl AttachmentIdMint {
    /// Seeds the counter from a millisecond timestamp. Only the seed
    /// comes from the clock; later ids never re-read it, which is what
    /// makes same-millisecond batches disjoint.
    pub fn new(now_ms: u64) -> Self {
        Self {
            next: now_ms as u32,
        }
    }

    pub fn next_id(&mut self) -> u32 {
        let id = self.next;
        self.next = self.next.wrapping_add(1);
        id
    }
}

thread_local! {
    static ATTACHMENT_ID_MINT: RefCell<Option<AttachmentIdMint>> =
        const { RefCell::new(None) };
}

/// Next page-unique attachment id. One mint per page (thread local),
/// seeded from `Date::now()` on first use.
fn next_attachment_id() -> u32 {
    ATTACHMENT_ID_MINT.with(|slot| {
        let mut slot = slot.borrow_mut();
        let mint = slot.get_or_insert_with(|| AttachmentIdMint::new(js_sys::Date::now() as u64));
        mint.next_id()
    })
}

pub fn data_url_payload(url: &str) -> Result<(String, String), String> {
    let rest = url
        .strip_prefix("data:")
        .ok_or_else(|| "not a data url".to_string())?;
    let (meta, data) = rest
        .split_once(',')
        .ok_or_else(|| "bad data url".to_string())?;
    if !meta.contains("base64") {
        return Err("expected base64".into());
    }
    let mime = meta.split(';').next().unwrap_or("").to_string();
    if data.is_empty() {
        return Err("attachment is empty".into());
    }
    Ok((mime, data.to_string()))
}

pub fn revoke_preview(url: &str) {
    if url.starts_with("blob:") {
        let _ = web_sys::Url::revoke_object_url(url);
    }
}

pub async fn upload_attachment(
    base: &str,
    token: &str,
    session_id: &str,
    name: &str,
    mime: &str,
    data_b64: &str,
) -> Result<Uploaded, String> {
    let value = api::post_json_value(
        base,
        token,
        "/v1/attachments",
        serde_json::json!({
            "name": name,
            "mime": mime,
            "data": data_b64,
            "sessionId": session_id,
        }),
    )
    .await?;
    serde_json::from_value(value).map_err(|e| e.to_string())
}

pub fn enqueue_file_list(
    list: web_sys::FileList,
    pending: RwSignal<Vec<PendingAttachment>>,
    status: RwSignal<String>,
) {
    for i in 0..list.length() {
        let Some(file) = list.item(i) else { continue };
        let name = file.name();
        let declared = file.type_();
        let size = file.size();
        let size_u = if size.is_finite() && size > 0.0 {
            size as u64
        } else {
            0
        };
        let already =
            pending.with_untracked(|rows| rows.iter().filter(|p| p.error.is_empty()).count());
        let id = next_attachment_id();
        if let Err(msg) = accept_local(already, size_u) {
            pending.update(|rows| {
                rows.push(PendingAttachment {
                    id,
                    name,
                    mime: declared,
                    bytes: size_u,
                    error: msg,
                    ..PendingAttachment::default()
                })
            });
            status.set("That file was not attached.".into());
            continue;
        }
        let preview = if declared.starts_with("image/") {
            web_sys::Url::create_object_url_with_blob(&file).unwrap_or_default()
        } else {
            String::new()
        };
        pending.update(|rows| {
            rows.push(PendingAttachment {
                id,
                name: name.clone(),
                mime: declared.clone(),
                bytes: size_u,
                preview,
                ..PendingAttachment::default()
            })
        });
        let Ok(reader) = web_sys::FileReader::new() else {
            mark_error(pending, id, "Could not read that file.");
            continue;
        };
        let reader_cb = reader.clone();
        let onload = Closure::once(move |_ev: web_sys::Event| {
            let result = reader_cb.result().unwrap_or(JsValue::NULL);
            let text = result.as_string().unwrap_or_default();
            match data_url_payload(&text) {
                Ok((mime, data)) => {
                    pending.update(|rows| {
                        if let Some(row) = rows.iter_mut().find(|r| r.id == id) {
                            if !mime.is_empty() {
                                row.mime = mime;
                            }
                            row.data_b64 = data;
                        }
                    });
                }
                Err(err) => mark_error(pending, id, &err),
            }
        });
        reader.set_onload(Some(onload.as_ref().unchecked_ref()));
        onload.forget();
        let onerr = Closure::once(move |_ev: web_sys::Event| {
            mark_error(pending, id, "Could not read that file.");
        });
        reader.set_onerror(Some(onerr.as_ref().unchecked_ref()));
        onerr.forget();
        if reader.read_as_data_url(&file).is_err() {
            mark_error(pending, id, "Could not read that file.");
        }
    }
}

fn mark_error(pending: RwSignal<Vec<PendingAttachment>>, id: u32, msg: &str) {
    let msg = msg.to_string();
    pending.update(|rows| {
        if let Some(row) = rows.iter_mut().find(|r| r.id == id) {
            if row.error.is_empty() {
                row.error = msg.clone();
            }
            row.data_b64.clear();
        }
    });
}

pub fn dictation_available() -> bool {
    // Host unit tests rank the palette without a JS runtime. Speech
    // recognition only exists in the browser.
    if !cfg!(target_arch = "wasm32") {
        return false;
    }
    let Some(win) = web_sys::window() else {
        return false;
    };
    has_ctor(&win, "SpeechRecognition") || has_ctor(&win, "webkitSpeechRecognition")
}

fn has_ctor(win: &web_sys::Window, name: &str) -> bool {
    js_sys::Reflect::get(win.as_ref(), &JsValue::from_str(name))
        .ok()
        .map(|v| v.is_function())
        .unwrap_or(false)
}

thread_local! {
    static DICTATION: RefCell<Option<JsValue>> = const { RefCell::new(None) };
}

/// Starts dictation, or stops it when one is already running.
/// Returns whether it is now listening. The recognition object stays in a
/// thread local so the view closure does not have to be `Send`.
pub fn toggle_dictation(
    on_text: impl Fn(String) + 'static,
    on_done: impl Fn(String) + 'static,
) -> Result<bool, String> {
    let running = DICTATION.with(|slot| slot.borrow().is_some());
    if running {
        DICTATION.with(|slot| {
            if let Some(rec) = slot.borrow().clone() {
                let _ = call0(&rec, "stop");
            }
            *slot.borrow_mut() = None;
        });
        return Ok(false);
    }
    let win = web_sys::window().ok_or_else(|| "no window".to_string())?;
    let ctor = speech_ctor(&win).ok_or_else(|| "speech API unavailable".to_string())?;
    let rec = js_sys::Reflect::construct(&ctor, &js_sys::Array::new())
        .map_err(|_| "could not start speech".to_string())?;
    let _ = js_sys::Reflect::set(&rec, &JsValue::from_str("interimResults"), &JsValue::FALSE);
    let _ = js_sys::Reflect::set(&rec, &JsValue::from_str("continuous"), &JsValue::FALSE);
    let on_text = Rc::new(on_text);
    let on_done: Rc<dyn Fn(String)> = Rc::new(on_done);
    let on_result = Closure::wrap(Box::new(move |ev: JsValue| {
        if let Some(text) = transcript_of(&ev) {
            let text = text.trim().to_string();
            if !text.is_empty() {
                on_text(text);
            }
        }
    }) as Box<dyn FnMut(JsValue)>);
    let _ = js_sys::Reflect::set(&rec, &JsValue::from_str("onresult"), on_result.as_ref());
    on_result.forget();
    let done_end = on_done.clone();
    let on_end = Closure::wrap(Box::new(move |_ev: JsValue| {
        DICTATION.with(|slot| *slot.borrow_mut() = None);
        done_end(String::new());
    }) as Box<dyn FnMut(JsValue)>);
    let _ = js_sys::Reflect::set(&rec, &JsValue::from_str("onend"), on_end.as_ref());
    on_end.forget();
    let done_err = on_done;
    let on_error = Closure::wrap(Box::new(move |ev: JsValue| {
        let code = js_sys::Reflect::get(&ev, &JsValue::from_str("error"))
            .ok()
            .and_then(|v| v.as_string())
            .unwrap_or_default();
        done_err(speech_error(&code));
    }) as Box<dyn FnMut(JsValue)>);
    let _ = js_sys::Reflect::set(&rec, &JsValue::from_str("onerror"), on_error.as_ref());
    on_error.forget();
    call0(&rec, "start")?;
    DICTATION.with(|slot| *slot.borrow_mut() = Some(rec));
    Ok(true)
}

fn speech_ctor(win: &web_sys::Window) -> Option<js_sys::Function> {
    for name in ["SpeechRecognition", "webkitSpeechRecognition"] {
        let value = js_sys::Reflect::get(win.as_ref(), &JsValue::from_str(name)).ok()?;
        if let Ok(fun) = value.dyn_into::<js_sys::Function>() {
            return Some(fun);
        }
    }
    None
}

fn speech_error(code: &str) -> String {
    match code {
        "not-allowed" | "service-not-allowed" => "Microphone blocked by the browser.".into(),
        "no-speech" => "No speech heard.".into(),
        "aborted" | "" => String::new(),
        "audio-capture" => "No microphone is available.".into(),
        other => format!("Speech failed ({other})."),
    }
}

fn transcript_of(ev: &JsValue) -> Option<String> {
    let results = js_sys::Reflect::get(ev, &JsValue::from_str("results")).ok()?;
    let len = js_sys::Reflect::get(&results, &JsValue::from_str("length"))
        .ok()?
        .as_f64()? as u32;
    if len == 0 {
        return None;
    }
    let last = js_sys::Reflect::get(&results, &JsValue::from_f64((len - 1) as f64)).ok()?;
    let is_final = js_sys::Reflect::get(&last, &JsValue::from_str("isFinal"))
        .ok()
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    if !is_final {
        return None;
    }
    let alt = js_sys::Reflect::get(&last, &JsValue::from_f64(0.0)).ok()?;
    js_sys::Reflect::get(&alt, &JsValue::from_str("transcript"))
        .ok()?
        .as_string()
}

fn call0(obj: &JsValue, method: &str) -> Result<(), String> {
    let fun = js_sys::Reflect::get(obj, &JsValue::from_str(method))
        .map_err(|_| method.to_string())?
        .dyn_into::<js_sys::Function>()
        .map_err(|_| method.to_string())?;
    fun.call0(obj).map(|_| ()).map_err(|e| format!("{e:?}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn failed_send_keeps_text_typed_during_upload() {
        assert_eq!(merge_failed_send("", "caption"), "caption");
        assert_eq!(merge_failed_send("next", "caption"), "caption next");
        assert_eq!(merge_failed_send("caption", "caption"), "caption");
        let failed = vec![PendingAttachment {
            id: 1,
            name: "a.png".into(),
            ..PendingAttachment::default()
        }];
        let added = vec![PendingAttachment {
            id: 2,
            name: "b.png".into(),
            ..PendingAttachment::default()
        }];
        let merged = merge_failed_files(failed, added);
        assert_eq!(merged.len(), 2);
        assert_eq!(merged[0].id, 1);
        assert_eq!(merged[1].id, 2);
    }

    fn rows(ids: std::ops::RangeInclusive<u32>) -> Vec<PendingAttachment> {
        ids.map(|id| PendingAttachment {
            id,
            name: format!("f{id}.png"),
            ..PendingAttachment::default()
        })
        .collect()
    }

    #[test]
    fn attachment_ids_are_disjoint_across_same_millisecond_batches() {
        // One mint seeded at a fixed millisecond, as in the page. Two
        // batches enqueued "in the same millisecond" — the second batch's
        // indices restart at 0, which is exactly what collided when the
        // id was Date::now()*16+index.
        let mut mint = AttachmentIdMint::new(1_700_000_000_123);
        let batch1: Vec<u32> = (0..3).map(|_| mint.next_id()).collect();
        let batch2: Vec<u32> = (0..3).map(|_| mint.next_id()).collect();
        for id in &batch2 {
            assert!(!batch1.contains(id), "id {id} minted twice");
        }
        // Seeded from the clock, then strictly counting up.
        assert_eq!(batch1[0], 1_700_000_000_123u64 as u32);
        assert!(batch1.windows(2).all(|w| w[1] == w[0] + 1));
        assert_eq!(batch2[0], batch1[2] + 1);
    }

    #[test]
    fn attachment_id_mint_wraps_without_repeating_early_ids() {
        let mut mint = AttachmentIdMint::new(u64::from(u32::MAX) - 1);
        let ids: Vec<u32> = (0..4).map(|_| mint.next_id()).collect();
        assert_eq!(ids, vec![u32::MAX - 1, u32::MAX, 0, 1]);
    }

    #[test]
    fn merge_failed_files_caps_at_max_and_reports_dropped() {
        // #1652: failed 8 + current 8 used to restore all 16.
        let (merged, dropped) = merge_failed_files_capped(rows(1..=8), rows(101..=108));
        assert_eq!(merged.len(), MAX_ATTACHMENTS);
        assert_eq!(dropped, 8);
        // Failed batch retained, in order, at the front.
        assert_eq!(
            merged.iter().map(|r| r.id).collect::<Vec<_>>(),
            (1..=8).collect::<Vec<_>>()
        );
        // The plain wrapper enforces the same cap.
        assert_eq!(
            merge_failed_files(rows(1..=8), rows(101..=108)).len(),
            MAX_ATTACHMENTS
        );
        assert_eq!(
            restore_drop_notice(8),
            "8 attachments were not restored: only 8 attachments per message"
        );
        assert_eq!(
            restore_drop_notice(1),
            "1 attachment was not restored: only 8 attachments per message"
        );
    }

    #[test]
    fn merge_failed_files_under_cap_and_dedupe_unchanged() {
        // Under the cap nothing is dropped and order is failed-first.
        let (merged, dropped) = merge_failed_files_capped(rows(1..=3), rows(4..=5));
        assert_eq!(merged.len(), 5);
        assert_eq!(dropped, 0);
        // Exactly at the cap is not a drop.
        let (merged, dropped) = merge_failed_files_capped(rows(1..=5), rows(6..=8));
        assert_eq!(merged.len(), MAX_ATTACHMENTS);
        assert_eq!(dropped, 0);
        // Deduped rows are the same file, not a cap drop: 8 failed, 8
        // current, 4 of them duplicates of the failed batch -> 12
        // distinct, 4 dropped by the cap, not 8.
        let (merged, dropped) = merge_failed_files_capped(rows(1..=8), rows(5..=12));
        assert_eq!(merged.len(), MAX_ATTACHMENTS);
        assert_eq!(dropped, 4);
    }

    #[test]
    fn layout_defaults_to_cockpit() {
        assert_eq!(normalize_layout(""), "cockpit");
        assert_eq!(normalize_layout("conversation"), "conversation");
        assert_eq!(normalize_layout("chat"), "cockpit");
    }

    #[test]
    fn shell_class_names_drawers_only_in_conversation() {
        assert_eq!(shell_class(false, "cockpit", true, true), "shell");
        assert_eq!(shell_class(true, "cockpit", false, false), "shell focus");
        assert_eq!(
            shell_class(true, "conversation", true, false),
            "shell layout-conversation drawer-sessions"
        );
        assert_eq!(
            shell_class(false, "conversation", true, true),
            "shell layout-conversation drawer-sessions drawer-panel"
        );
    }

    #[test]
    fn accept_local_enforces_count_and_size() {
        assert!(accept_local(0, 10).is_ok());
        assert!(accept_local(MAX_ATTACHMENTS, 10).is_err());
        assert!(accept_local(0, 0).is_err());
        assert!(accept_local(0, MAX_ATTACHMENT_BYTES as u64 + 1).is_err());
    }

    #[test]
    fn data_url_and_reconnect_delay() {
        let (mime, data) = data_url_payload("data:image/png;base64,abcd").unwrap();
        assert_eq!(mime, "image/png");
        assert_eq!(data, "abcd");
        assert!(data_url_payload("nope").is_err());
        assert_eq!(reconnect_delay_ms(0), 1000);
        assert_eq!(reconnect_delay_ms(1), 2000);
        assert_eq!(reconnect_delay_ms(3), 8000);
        assert_eq!(reconnect_delay_ms(9), 8000);
    }
}

/// Page wiring for the shell contribution in `src/shell/contrib/chat_mode.rs`.
/// The shell boots before App's signals exist, so App installs them here
/// (same late-bind shape as `shell::HostBridge` and the status centre's
/// host) and the slot render / palette commands read them.
#[derive(Clone)]
pub struct LayoutHost {
    pub layout: RwSignal<String>,
    pub set_layout: Rc<dyn Fn(&str)>,
}

thread_local! {
    static LAYOUT_HOST: RefCell<Option<LayoutHost>> = const { RefCell::new(None) };
}

pub fn set_host(host: LayoutHost) {
    LAYOUT_HOST.with(|slot| *slot.borrow_mut() = Some(host));
}

fn layout_host() -> Option<LayoutHost> {
    LAYOUT_HOST.with(|slot| slot.borrow().clone())
}

/// Current layout ("cockpit" unless the page installed "conversation").
pub fn current_layout() -> String {
    layout_host()
        .map(|host| host.layout.get_untracked())
        .unwrap_or_else(|| "cockpit".into())
}

/// Palette entry point: switch the layout through the page's own setter
/// (which persists `strike.layout` and closes the drawers for cockpit).
pub fn host_set_layout(next: &str) -> Result<(), String> {
    let host = layout_host().ok_or_else(|| "Layout is not ready.".to_string())?;
    (host.set_layout)(next);
    Ok(())
}

/// Slot render for the `layout` slot: the pre-shell header toggle,
/// unchanged — a segmented Cockpit / Conversation pair whose buttons
/// carry `data-layout` (the smoke and UAT drivers click them).
pub fn layout_view() -> AnyView {
    let Some(host) = layout_host() else {
        return view! { <span></span> }.into_any();
    };
    let layout = host.layout;
    let set_cockpit = host.set_layout.clone();
    let set_conversation = host.set_layout.clone();
    view! {
        <div class="segmented layout-toggle" role="tablist" aria-label="Layout">
            <button
                type="button"
                data-layout="cockpit"
                class=move || if layout.get() != "conversation" { "seg on" } else { "seg" }
                on:click=move |_| set_cockpit("cockpit")
            >
                "Cockpit"
            </button>
            <button
                type="button"
                data-layout="conversation"
                class=move || if layout.get() == "conversation" { "seg on" } else { "seg" }
                on:click=move |_| set_conversation("conversation")
            >
                "Conversation"
            </button>
        </div>
    }
    .into_any()
}
